std::size_t modelCount() { return sizeof(models)/sizeof(models[0]); }
const Model& modelAt(std::size_t index) { return models[index < modelCount() ? index : 0]; }
const Model* findModel(const std::string& name) {
    for (const auto& model : models) if (name == model.name) return &model;
    return nullptr;
}
